style.css:
@-moz-document domain("roblox.com") {
:root {
    --pink-bg: #F8D0DF;
    --pink-light: #FFEAF2;
    --pink-soft: #FFD2E3;
    --pink-medium: #FFC1D9;
    --pink-strong: #F59CBD;
    --pink-dark: #DF78A5;
    --pink-text: #A85D7C;
    --white: #FFFFFF;
}

/* MAIN PAGE BACKGROUND */
html, body, #container-main,
.content, .home-container, .section-content {
    background-color: var(--pink-bg) !important;
}

/* TOP NAVIGATION - DEEPER PINK */
#header, .navbar, .navbar-fixed-top {
    background: #FFC1D9 !important;
    border-bottom: 1px solid #F59CBD !important;
}

/* TOP NAVIGATION TEXT AND ICONS */
#header a,
.navbar a,
.navbar-fixed-top a {
    color: #A34470 !important;
}

/* LEFT SIDEBAR */
#navigation, .left-navigation,
.navigation, .menu-vertical {
    background-color: var(--white) !important;
}

/* SIDEBAR HOVER */
#navigation a:hover,
.left-navigation a:hover,
.menu-vertical a:hover {
    background-color: var(--pink-light) !important;
    border-radius: 12px !important;
}

/* SEARCH BARS */
input, input[type="text"],
input[type="search"], .search-input,
#navbar-search-input {
    border-color: var(--pink-soft) !important;
    border-radius: 20px !important;
}

input:focus, .search-input:focus {
    border-color: var(--pink-strong) !important;
    box-shadow: 0 0 0 2px var(--pink-light) !important;
}

/* GENERAL BUTTONS */
button, .btn-control,
.btn-secondary-md, .btn-secondary-lg {
    border-radius: 12px !important;
}

/* DOWNLOAD BUTTON */
#navbar-download, .navbar-download,
a.btn-growth-md, button.btn-growth-md,
.btn-growth-md, a[href*="download"] {
    background: var(--pink-strong) !important;
    background-color: var(--pink-strong) !important;
    border-color: var(--pink-strong) !important;
    color: white !important;
    border-radius: 20px !important;
}

#navbar-download:hover,
.navbar-download:hover,
.btn-growth-md:hover,
a[href*="download"]:hover {
    background: var(--pink-dark) !important;
}

/* GAME CARDS */
.game-card, .game-card-container,
.list-item, .game-card-link {
    border-radius: 14px !important;
}

.game-card:hover, .game-card-container:hover {
    box-shadow: 0 4px 14px rgba(245,156,189,.25) !important;
}

/* GAME PLAY BUTTON */
.btn-common-play-game-lg,
.btn-common-play-game-md,
.game-play-button {
    background: var(--pink-strong) !important;
    border-color: var(--pink-strong) !important;
    color: white !important;
    border-radius: 12px !important;
}

.btn-common-play-game-lg:hover,
.btn-common-play-game-md:hover,
.game-play-button:hover {
    background: var(--pink-dark) !important;
}

/* DROPDOWNS AND POPUPS */
.dropdown-menu, .popover,
.tooltip, .modal-content, .modal-dialog {
    background-color: var(--white) !important;
    border: 1px solid var(--pink-soft) !important;
    border-radius: 14px !important;
}

.dropdown-menu li:hover,
.dropdown-menu a:hover {
    background-color: var(--pink-light) !important;
}

/* FRIENDS AND CHAT PANELS */
.chat-container, #chat,
.friend-tile, .friends-list {
    border-radius: 14px !important;
}

/* TOP-RIGHT FRIENDS AND CHAT ICONS */
#btr-navbar-friends,
#btr-navbar-messages {
    position: relative !important;
    top: 0 !important;
    transform: none !important;
    align-self: center !important;
}

/* AVATAR EDITOR TABS */
#horizontal-tabs .rbx-tab,
#horizontal-tabs .rbx-tab.seven-tab,
#horizontal-tabs .rbx-tab-heading {
    background-color: var(--pink-light) !important;
    color: var(--pink-text) !important;
    border-radius: 12px !important;
}

#horizontal-tabs .rbx-tab:hover,
#horizontal-tabs .rbx-tab-heading:hover {
    background-color: var(--pink-soft) !important;
}

#horizontal-tabs .rbx-tab.active,
#horizontal-tabs .rbx-tab.active .rbx-tab-heading {
    background-color: var(--pink-soft) !important;
    color: var(--pink-text) !important;
}

/* FRIENDS PAGE - FRIEND CARDS */
ul.hlist.avatar-cards .avatar-card-container,
.avatar-card-container {
    background-color: #FFEAF2 !important;
    border: 1px solid #FFD2E3 !important;
    border-radius: 14px !important;
}

ul.hlist.avatar-cards .avatar-card-container:hover {
    background-color: #FFDCE9 !important;
}

/* FRIEND CARD CONTENT */
.avatar-card-content,
.avatar-card-caption {
    background-color: transparent !important;
}

/* LOGIN PAGE BACKGROUND */
.login-container,
.login-container .login-form,
.login-form-container,
section.login-container {
    background-color: #FFF7FB !important;
}

/* LOGIN PANEL */
.login-container .login-form,
.login-form-container {
    background: #FFF7FB !important;
    border: 1px solid #FFD2E3 !important;
    border-radius: 18px !important;
    box-shadow: 0 5px 25px rgba(223,120,165,.15) !important;
}

/* LOGIN PAGE TEXT */
.login-container h1,
.login-container h2,
.login-container label,
.login-container p,
.login-container a {
    color: #A85D7C !important;
}

/* LOGIN INPUT FIELDS */
.login-container input,
.login-form-container input {
    background: white !important;
    color: #75445A !important;
    border: 1px solid #FFD2E3 !important;
    border-radius: 20px !important;
}

.login-container input::placeholder,
.login-form-container input::placeholder {
    color: #B98DA1 !important;
}

/* LOGIN AND SIGN-UP BUTTONS */
.login-button,
.btn-login,
.login-container button[type="submit"],
.login-form-container button,
.signup-button,
a[href*="signup"] {
    background: #F59CBD !important;
    background-color: #F59CBD !important;
    border: 1px solid #F59CBD !important;
    color: white !important;
    border-radius: 12px !important;
}

.login-button:hover,
.btn-login:hover,
.login-container button[type="submit"]:hover,
.login-form-container button:hover,
.signup-button:hover,
a[href*="signup"]:hover {
    background: #DF78A5 !important;
    border-color: #DF78A5 !important;
    color: white !important;
}

/* LOGIN PAGE LINKS */
.login-container a,
.login-form-container a {
    color: #DF78A5 !important;
}

/* SIGN-UP BUTTON IN TOP NAV */
#navbar-signup,
.navbar-signup,
a[href*="signup"] {
    background-color: #F59CBD !important;
    border-color: #F59CBD !important;
    color: white !important;
}

/* SCROLLBAR */
::-webkit-scrollbar {
    width: 9px !important;
}

::-webkit-scrollbar-track {
    background: var(--pink-bg) !important;
}

::-webkit-scrollbar-thumb {
    background: var(--pink-medium) !important;
    border-radius: 20px !important;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--pink-dark) !important;
}

/* TEXT SELECTION */
::selection {
    background: var(--pink-medium) !important;
    color: white !important;
}

/* CHECKBOXES */
input[type="checkbox"] {
    accent-color: var(--pink-strong) !important;
}

/* REMOVE ROPRO VERIFY USER BOX */
li.rbx-upgrade-now {
    display: none !important;
}

/* PINK FAVOURITE STAR AND LIKE THUMB */

/* Selected favourite and like buttons */
.favorite-button.active,
.favorite-button.selected,
.like-button.active,
.like-button.selected,
button[aria-pressed="true"] {
    background-color: #F59CBD !important;
    border-color: #F59CBD !important;
    color: white !important;
}

/* Favourite star icons */
.icon-favorite.favorited,
.icon-star.favorited,
.favorite-button.active svg {
    color: #F59CBD !important;
    fill: #F59CBD !important;
}

/* Like thumb icons */
.icon-thumbs-up.liked,
.like-button.active svg {
    color: #F59CBD !important;
    fill: #F59CBD !important;
}

/* HOVER EFFECTS */
.favorite-button:hover,
.like-button:hover {
    color: #DF78A5 !important;
}
}
